cssCode:
.toggle-wrap {
  width: 80px; height: 40px;
  background: #222;
  border-radius: 20px;
  position: relative;
  cursor: pointer;
  box-shadow: inset 0 2px 5px rgba(0,0,0,0.8);
  transition: background 0.4s;
}
.toggle-wrap.active { background: #00ffcc; box-shadow: 0 0 20px rgba(0, 255, 204, 0.4), inset 0 2px 5px rgba(0,0,0,0.2); }
.toggle-circle {
  width: 32px; height: 32px;
  background: #fff;
  border-radius: 50%;
  position: absolute;
  top: 4px; left: 4px;
  transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  box-shadow: 0 2px 5px rgba(0,0,0,0.5);
}
.toggle-wrap.active .toggle-circle { transform: translateX(40px); }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const toggle = document.createElement('div');
toggle.className = 'toggle-wrap';

const circle = document.createElement('div');
circle.className = 'toggle-circle';

toggle.appendChild(circle);
c.appendChild(toggle);

toggle.addEventListener('click', () => {
  toggle.classList.toggle('active');
});
